def fib(n):
    if n <= 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

D_small = []
for k in range(2, 11):
    D_small.append(fib(k))

print(f"Fibonacci differences D_{10}: {D_small}")
